{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.izf_orders_summary as with all_dates as ( select DISTINCT c.date_day, upper(d.sku_style) sku_style, upper(d.sku_size) sku_size FROM maplemonk.izf_inventory_fact_items AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2024-01-01\', CURRENT_DATE())) AS date_day ) AS c WHERE upper(d.sku_size) in (\'XXS\',\'XS\',\'S\',\'M\',\'L\',\'XL\',\'XXL\',\'FS\') ), sales as ( select a.sku_size as size, a.sku_style as style, a.date_day order_date, s.order_count, s.order_quantity, s.selling_price, s.discount, from all_dates a left join (select upper(sku_size) as size, upper(sku_style) as style, order_date, ifnull(count(DISTINCT order_id), 0) as order_count, sum(ifnull(quantity,0)) as order_quantity, sum(ifnull(selling_price,0)) as selling_price, sum(ifnull(discount, 0)) as discount from maplemonk.izf_sales_consolidated s group by 1,2,3 ) s on lower(a.sku_size) = lower(s.size) and lower(a.sku_style) = lower(s.style) and date(a.date_day) = date(s.order_date) ), returns_37_7 as ( SELECT upper(sku_style) sku_style, upper(sku_size) sku_size, count(DISTINCT order_id) as order_count_7_37, count(DISTINCT CASE WHEN lower(return_type) = \'return\' THEN ordeR_id END) as customer_return_count_7_37, count(DISTINCT CASE WHEN lower(return_type) = \'rto\' THEN ordeR_id END) as rto_return_count_7_37, count(DISTINCT CASE WHEN lower(return_type) in (\'return\',\'rto\') THEN ordeR_id END) as overall_return_count_7_37 from maplemonk.izf_returns_consolidated where order_date >= date_add(current_date(), interval -37 DAY) AND order_date < date_add(current_date(), interval -7 DAY) group by 1,2 ), returns as ( select upper(sku_style) sku_style, upper(sku_size) sku_size, date(order_date) order_date, sum(case when lower(return_type) like \'%return%\' then ifnull(TOTAL_RETURNED_QUANTITY,0) else 0 end) as Customer_Returns, sum(case when lower(return_type) like \'%rto%\' then ifnull(TOTAL_RETURNED_QUANTITY,0) else 0 end) as RTO_Returns, sum(case when lower(return_type) like any (\'%rto%\',\'%return%\') then ifnull(TOTAL_RETURNED_QUANTITY,0) else 0 end) as Overall_Returns from maplemonk.izf_returns_consolidated group by 1,2,3 ), inventory as ( select upper(sku_style) sku_style, upper(sku_size) sku_size, sum(ifnull(Available_Inventory,0)) Available_Inventory from maplemonk.izf_inventory_fact_items where date_diff(current_date(),data_fetch_date,DAY) = 1 group by 1,2 ), inventory_metrics as ( select upper(sku_style) sku_style, upper(sku_size) sku_size, date(data_fetch_date) as date, sum(ifnull(sold_quantity_7_days,0)) sold_quantity_7_days, sum(ifnull(sold_quantity_mtd,0)) sold_quantity_mtd, sum(ifnull(Sold_Quantity_30_Days,0)) Sold_Quantity_30_Days, avg(ifnull(grn_30_Days,0)) grn_30_Days, avg(ifnull(opening_inventory_30_days_ago,0)) opening_inventory_30_days_ago from maplemonk.izf_inventory_fact_items group by 1,2,3 ), scr as ( select upper(sku_style) sku_style, safe_divide(sum(has_adequate_inventory), count(*)) AS Size_Coverage_Ratio, from maplemonk.izf_inventory_size_coverage where data_fetch_date = date_sub(current_date(), interval 1 DAY) group by 1 ) select size, s.style, lt.sku_status, s.order_date, order_count, order_quantity, selling_price, discount, i.Available_Inventory, im.sold_quantity_7_days, im.sold_quantity_mtd, im.Sold_Quantity_30_Days, im.grn_30_Days, im.opening_inventory_30_days_ago, r.Customer_Returns, r.RTO_Returns, r.Overall_Returns, r377.customer_return_count_7_37, r377.rto_return_count_7_37, r377.order_count_7_37, scr.Size_Coverage_Ratio from sales s left join inventory i on lower(s.style) = lower(i.sku_style) and lower(s.size) = lower(i.sku_size) left join returns_37_7 r377 on lower(s.style) = lower(r377.sku_style) and lower(s.size) = lower(r377.sku_size) left join returns r on lower(s.style) = lower(r.sku_style) and lower(s.size) = lower(r.sku_size) and date(s.order_date) = date(r.order_date) left join scr on lower(scr.sku_style) = lower(s.style) left join inventory_metrics im on lower(s.style) = lower(im.sku_style) and lower(s.size) = lower(im.sku_size) and date(s.order_date) = date(im.date) left join (select upper((replace(style,\' \',\'\'))) style,sku_status from izf-wh.maplemonk.google_sheets_po_style_lead_time qualify row_number() over (partition by upper((replace(style,\' \',\'\'))) order by 1)= 1 ) lt on lower(s.style) = lower(lt.style) where lt.style is not null ; create or replace table maplemonk.izf_orders_monthly_summary as with all_months as ( select DISTINCT last_day(c.date_day,month) as month, upper(d.sku_style) sku_style, upper(d.sku_size) sku_size FROM maplemonk.izf_inventory_fact_items AS d CROSS JOIN ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE \'2024-01-01\', CURRENT_DATE())) AS date_day ) AS c WHERE upper(d.sku_size) in (\'XXS\',\'XS\',\'S\',\'M\',\'L\',\'XL\',\'XXL\',\'FS\') ), sales as ( select a.sku_size as size, a.sku_style as style, a.month, s.order_count, s.order_quantity, s.selling_price, s.discount, from all_months a left join (select upper(sku_size) as size, upper(sku_style) as style, last_day(order_date,month) as order_month, ifnull(count(DISTINCT order_id), 0) as order_count, sum(ifnull(quantity,0)) as order_quantity, sum(ifnull(selling_price,0)) as selling_price, sum(ifnull(discount, 0)) as discount from maplemonk.izf_sales_consolidated s group by 1,2,3 ) s on lower(a.sku_size) = lower(s.size) and lower(a.sku_style) = lower(s.style) and date(a.month) = date(s.order_month) ), returns_monthly_37_7 as ( SELECT m.month, UPPER(m.sku_style) AS sku_style, UPPER(m.sku_size) AS sku_size, COUNT(DISTINCT r.order_id) AS order_count_7_37, COUNT(DISTINCT CASE WHEN LOWER(r.return_type) = \'return\' THEN r.order_id END) AS customer_return_count_7_37, COUNT(DISTINCT CASE WHEN LOWER(r.return_type) = \'rto\' THEN r.order_id END) AS rto_return_count_7_37, COUNT(DISTINCT CASE WHEN LOWER(r.return_type) IN (\'return\',\'rto\') THEN r.order_id END) AS overall_return_count_7_37 FROM all_months m LEFT JOIN maplemonk.izf_returns_consolidated r ON UPPER(m.sku_style) = UPPER(r.sku_style) AND UPPER(m.sku_size) = UPPER(r.sku_size) AND r.order_date >= DATE_ADD(m.month, INTERVAL -37 DAY) AND r.order_date < DATE_ADD(m.month, INTERVAL -7 DAY) GROUP BY 1, 2, 3 ), inventory_monthly as ( select upper(sku_style) sku_style, upper(sku_size) sku_size, data_fetch_date as month, sum(ifnull(Available_Inventory,0)) Available_Inventory, sum(ifnull(sold_quantity_7_days,0)) sold_quantity_7_days, sum(ifnull(sold_quantity_mtd,0)) sold_quantity_mtd, sum(ifnull(Sold_Quantity_30_Days,0)) Sold_Quantity_30_Days, avg(ifnull(grn_30_Days,0)) grn_30_Days, avg(ifnull(opening_inventory_30_days_ago,0)) opening_inventory_30_days_ago from maplemonk.izf_inventory_fact_items where data_fetch_date = last_day(DATA_FETCH_DATE,month) group by 1,2,3 ), scr_monthly as ( select upper(sku_style) sku_style, data_fetch_date as month, safe_divide(sum(has_adequate_inventory), count(*)) AS Size_Coverage_Ratio, from maplemonk.izf_inventory_size_coverage where data_fetch_date = last_day(DATA_FETCH_DATE,month) group by 1,2 ) select size, s.style, lt.sku_status, case when upper(s.style) like \'B%\' then \'BASIXX\' else \'IZF\' end as brand, s.month, order_count, order_quantity, selling_price, discount, i.Available_Inventory, i.sold_quantity_7_days, i.sold_quantity_mtd, i.Sold_Quantity_30_Days, i.grn_30_Days, i.opening_inventory_30_days_ago, r377.customer_return_count_7_37, r377.rto_return_count_7_37, r377.order_count_7_37, scr.Size_Coverage_Ratio from sales s left join inventory_monthly i on lower(s.style) = lower(i.sku_style) and lower(s.size) = lower(i.sku_size) and date(s.month) = date(i.month) left join returns_monthly_37_7 r377 on lower(s.style) = lower(r377.sku_style) and lower(s.size) = lower(r377.sku_size) and date(s.month) = date(r377.month) left join scr_monthly scr on lower(scr.sku_style) = lower(s.style) and date(s.month) = date(scr.month) left join (select upper((replace(style,\' \',\'\'))) style,sku_status from izf-wh.maplemonk.google_sheets_po_style_lead_time qualify row_number() over (partition by upper((replace(style,\' \',\'\'))) order by 1)= 1 ) lt on lower(s.style) = lower(lt.style) where lt.style is not null ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
